        "hours = diurnal_jja[\"hour\"].values\n",
        "fig, axes = plt.subplots(2, 4, figsize=(18, 9), subplot_kw={\"projection\": ccrs.PlateCarree()})\n",
        "vmax = float(diurnal_jja.quantile(0.98))\n",
        "\n",
        "for ax, h in zip(axes.flat, hours):\n",
        "    f = diurnal_jja.sel(hour=h)\n",
        "    im = ax.pcolormesh(f[\"lon\"], f[\"lat\"], f, transform=ccrs.PlateCarree(),\n",
        "                       cmap=\"viridis\", vmin=0, vmax=vmax, shading=\"auto\")\n",
        "    ax.coastlines(resolution=\"10m\", linewidth=0.6)\n",
        "    ax.add_feature(cfeature.BORDERS, linewidth=0.5)\n",
        "    ax.set_extent([88, 98, 20, 30], crs=ccrs.PlateCarree())\n",
        "    ax.set_title(f\"{h:02d} UTC\")\n",
        "\n",
        "fig.colorbar(im, ax=axes, shrink=0.7, label=\"Precipitation (mm per 3 h)\")\n",
        "plt.show()"
